package com.example.smartpantrymanager;
import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.*;
public class RecipeDetailActivity extends AppCompatActivity{private ExecutorService executor;public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_recipe_detail);executor=Executors.newSingleThreadExecutor();final long id=getIntent().getLongExtra("id",-1);executor.execute(()->{Recipe r=new PantryDatabaseHelper(getApplicationContext()).getRecipe(id);if(r==null||isFinishing()||isDestroyed())return;runOnUiThread(()->{setTitle(r.getName());StringBuilder s=new StringBuilder("Required ingredients:\n");for(Recipe.RequiredIngredient i:r.getIngredients())s.append("• ").append(i.display()).append('\n');s.append("\nCooking instructions:\n").append(r.getMethod());((TextView)findViewById(R.id.recipe_detail_text)).setText(s.toString());});});}protected void onDestroy(){if(executor!=null)executor.shutdownNow();super.onDestroy();}}
